    /*
     * Add to the Predictions
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	InferenceEndpoint
     */
    public InferenceEndpoint addToPredictions( UUID parentId, Prediction addTo ) {
	    LOGGER.info("handling AssignPredictionsToInferenceEndpointEvent - " );
	    
	    InferenceEndpoint parentEntity = repository.findById(parentId).get();
	    Prediction child = registry.project( Prediction.class, addTo.getPredictionId());
	    
	    parentEntity.getPredictions().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Predictions
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	InferenceEndpoint
     */
	public InferenceEndpoint removeFromPredictions( UUID parentId, Prediction removeFrom ) {
	    LOGGER.info("handling RemovePredictionsFromInferenceEndpointEvent " );
	
	    InferenceEndpoint parentEntity = repository.findById(parentId).get();
	    Prediction child = registry.project( Prediction.class, removeFrom.getPredictionId());
	    
	    parentEntity.getPredictions().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



